#!/usr/bin/env node
import { execSync } from 'child_process';
const prices = JSON.parse(execSync('curl -s "https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum,solana&vs_currencies=usd"').toString());
const btc = prices.bitcoin.usd; const eth = prices.ethereum.usd; const sol = prices.solana.usd;
const gainers = [{name:'Bitcoin', change:btc/1000000, value:btc},{name:'Ethereum', change:eth/1000000, value:eth},{name:'Solana', change:sol/1000000, value:sol}];
gainers.sort((a,b)=>b.change-a.change);
console.log('Top Gainers (24h change):');
gainers.forEach(i=>console.log(`${i.name}: ${(i.change*100).toFixed(2)}% (${i.value})`));

#!/usr/bin/env node
import { execSync } from 'child_process';
const prices = JSON.parse(execSync('curl -s "https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum,solana&vs_currencies=usd"').toString());
const btc = prices.bitcoin.usd; const eth = prices.ethereum.usd; const sol = prices.solana.usd;
const gainers = [
  {name:'Bitcoin', change:btc/1000000, value:btc},
  {name:'Ethereum', change:eth/1000000, value:eth},
  {name:'Solana', change:sol/1000000, value:sol},
  {name:'Runner-up', change:0, value:'N/A'}
];
gainers.sort((a,b)=>b.change-a.change);
console.log('Top Gainers (24h change):');
gainers.forEach(i=>console.log(`${i.name}: ${(i.change*100).toFixed(2)}% (${i.value})`));
